head.script:
scwin.screenId = "jldods70208";

///////// 1. 변수 및 선언 영역 /////////

scwin.fileListDev = $c.util.getComponent('fileListDev');

scwin.rowCnt = 0;

scwin.lastRowIdx = 0;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "txa_refContn", attr: "label", fn: function () { return String(dma_fssFileInfo.get("refContn")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_fssFileInfo", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "fssFileInfo" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("fssFileInfo")) === ''); } }, { id: "c_when_31_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "IsModify" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("IsModify")) === 'TRUE'); } }, { id: "input_35", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "IsModify" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("IsModify")) === 'TRUE'); } }, { id: "c_when_46_txt", fn: function(){ return ((dma_fssFileInfo.get("formAdmInstTpCd") ?? (() => { throw new Error("unresolved:" + "fssFileInfo.formAdmInstTpCd"); })()) === '1'); } }, { id: "c_otherwise_47", fn: function(){ return (!(((dma_fssFileInfo.get("formAdmInstTpCd") ?? (() => { throw new Error("unresolved:" + "fssFileInfo.formAdmInstTpCd"); })()) === '1'))); } }, { id: "c_when_44", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "fssFileInfo" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("fssFileInfo")) !== ''); } }, { id: "c_otherwise_48", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "fssFileInfo" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("fssFileInfo")) !== ''))); } }, { id: "btn_saveAction", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "IsModify" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("IsModify")) === 'TRUE'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(fssfile vs attachfiledown) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70208.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_mpd_files_select_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files')); 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70208.btn_mpd_files_select_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_mpd_files_del_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); } 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70208.btn_mpd_files_del_onclick' }); }
};

/**
 * @event
 * @name scwin.input_35_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.input_35_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_35_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goSearch()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70208.input_35_onclick' }); }
};

/**
 * @event
 * @name scwin.txa_refContn_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.txa_refContn_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin txa_refContn_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.checkByte($c.util.getComponent("txa_refContn"))
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70208.txa_refContn_onkeyup' }); }
};

/**
 * @event
 * @name scwin.txa_refContn_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.txa_refContn_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin txa_refContn_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.checkByte($c.util.getComponent("txa_refContn"))
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70208.txa_refContn_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_saveAction_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_saveAction_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_saveAction_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.saveAction()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70208.btn_saveAction_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_goSearch = async function () {
    try { return await $c.data.downFile("/discls/fssFile.do", "", ($c.util.getComponent("dma_goSearchReq") ? $c.util.getComponent("dma_goSearchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fn_saveAction
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_saveAction = async function () {
    const sbmOptions = {
        id: "tx_fn_saveAction",
        method: "post",
        action: "/discls/fssFile.do?method=docFileUploadSave",
        ref: "dma_saveActionReq",
        target: "dlt_fssFileData=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods70208.tx_fn_saveAction" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_fssFileDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_fssFileDownload = async function () {
    try { return await $c.data.downFile("/discls/attachFileDown.do", "", ($c.util.getComponent("dma_fssFileDownloadReq") ? $c.util.getComponent("dma_fssFileDownloadReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.goSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSearch = async function () {
    /* sdd-asis-lifecycle:begin goSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchFrmObj = (document.fssSearchFrm || { elements: [] });
    $c.util.getComponent('dma_goSearchReq').set('method', "searchAllFile");
    searchFrmObj.action = "/discls/fssFile.do";
    searchFrmObj.target = "searchFssFile";
    $c.win.openPopup("", { id: "searchFssFile", scrollbars: true, resizable: false, width: "880", height: "800", type: "pageFramePopup" }, {});
    await scwin.tx_goSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setSelectedData
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_formCd formNm ipt_formVer sendPer
 * @returns
 * @hidden N
*/
scwin.setSelectedData = function (ipt_formCd, formNm, ipt_formVer, sendPer) {
    /* sdd-asis-lifecycle:begin fn_setSelectedData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_goSearchReq').set('formCd', ipt_formCd);
    $c.util.getComponent("ipt_formNm").setValue(formNm);
    $c.util.getComponent('dma_goSearchReq').set('formVer', ipt_formVer);
    $c.util.getComponent('txt_tdText').setLabel(sendPer);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isOpen
 * @author Inswave
 * @date 2026. 09. 29
 * @param opnObj
 * @returns
 * @hidden N
*/
scwin.isOpen = function (opnObj) {
    /* sdd-asis-lifecycle:begin fn_isOpen — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (opnObj.checked === true) {
        opnObj.value = "N";
        $c.util.getComponent('dma_goSearchReq').set('opnYN', "N");
    } else {
        opnObj.value = "Y";
        $c.util.getComponent('dma_goSearchReq').set('opnYN', "Y");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addFileRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addFileRow = function () { $c.util.onUploadClick($c.util.getComponent('mpd_files')); };


/**
 * @method
 * @name scwin.deleteFileRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.deleteFileRow = async function () { if (typeof scwin.btn_mpd_files_del_onclick === 'function') { await scwin.btn_mpd_files_del_onclick(); } };


/**
 * @method
 * @name scwin.deleteAttachFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIdx
 * @returns
 * @hidden N
*/
scwin.deleteAttachFile = function (rowIdx) {
    /* sdd-asis-lifecycle:begin deleteAttachFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const attachFileObj = $c.util.getComponent("attachFile_" + rowIdx);
    scwin.fileListDev.removeChild(attachFileObj);
    const delFiles = $c.util.getComponent('dma_goSearchReq').get('delFile') + rowIdx + ":";
    $c.util.getComponent('dma_goSearchReq').set('delFile', delFiles);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.saveAction
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_applNo_2
 * @returns
 * @hidden N
*/
scwin.saveAction = async function (ipt_applNo_2) {
    /* sdd-asis-lifecycle:begin fn_saveAction — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fileFrmObj = (document.fssFileFrm || { elements: [] });
    if (($c.util.getComponent('ipt_formNm').getValue() == null ? '' : String($c.util.getComponent('ipt_formNm').getValue())) === '') {
        await alertE("서식을 선택하십시오.");
        return false;
    }
    if ($c.str.trim($c.util.getComponent('txa_refContn').getValue()) === '') {
        await alertE("전달사항을 입력하십시오.");
        return false;
    }
    confirmF("저장하시겠습니까?", async function() {
            await scwin.tx_fn_saveAction();
            await alertE("저장되었습니다.", function() {
                    (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { console.error('[sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다)'); } })();
                    $c.win.closePopup();
            });
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delFileFirst
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.delFileFirst = function () {
    /* sdd-asis-lifecycle:begin delFileFirst — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (console.error('[sdd] 이 화면 문서에 #firstFile 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#firstFile")).html('<input type="file" name="attachFile[0]" style="width: 420px; height: 27px;">');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fssFileDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_applNo_2 fileSeq
 * @returns
 * @hidden N
*/
scwin.fssFileDownload = async function (ipt_applNo_2, fileSeq) {
    /* sdd-asis-lifecycle:begin fn_fssFileDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_goSearchReq').set('applNo', ipt_applNo_2);
    $c.util.getComponent('dma_goSearchReq').set('fileSeq', fileSeq);
    await scwin.tx_fn_fssFileDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.checkByte = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_CheckByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const standardByte = 4000;
    const contnByte = scwin.getByte(_obj);
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getByte = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0A') {
            iCounts += 2;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calcContn
 * @author Inswave
 * @date 2026. 09. 29
 * @param _contn _maximum
 * @returns
 * @hidden N
*/
scwin.calcContn = function (_contn, _maximum) {
    /* sdd-asis-lifecycle:begin fn_CalcContn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (escape(ch) === '%0A') {
            inc = 2;
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                inc = 1;
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }
